IF COL_LENGTH('gb_channel','recording_mode') IS NULL ALTER TABLE gb_channel ADD recording_mode NVARCHAR(16) NOT NULL CONSTRAINT df_gb_channel_recording_mode DEFAULT 'off';
UPDATE gb_channel SET recording_mode = CASE WHEN cloud_recording_enabled = 1 THEN 'continuous' ELSE 'off' END;
IF OBJECT_ID('gb_recording_plan','U') IS NULL CREATE TABLE gb_recording_plan (id BIGINT IDENTITY(1,1) PRIMARY KEY, name NVARCHAR(128) NOT NULL, description NVARCHAR(500) NOT NULL DEFAULT '', status SMALLINT NOT NULL DEFAULT 1, version BIGINT NOT NULL DEFAULT 1, owner_dept_id BIGINT NOT NULL, created_by BIGINT NOT NULL DEFAULT 0, updated_by BIGINT NOT NULL DEFAULT 0, created_at DATETIME2(3) NOT NULL, updated_at DATETIME2(3) NOT NULL, deleted_at DATETIME2(3));
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name='idx_recording_plan_dept_deleted') CREATE INDEX idx_recording_plan_dept_deleted ON gb_recording_plan(owner_dept_id,deleted_at);
IF OBJECT_ID('gb_recording_plan_period','U') IS NULL CREATE TABLE gb_recording_plan_period (id BIGINT IDENTITY(1,1) PRIMARY KEY, plan_id BIGINT NOT NULL, weekday SMALLINT NOT NULL, start_slot SMALLINT NOT NULL, end_slot SMALLINT NOT NULL, created_at DATETIME2(3) NOT NULL, updated_at DATETIME2(3) NOT NULL);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name='idx_recording_plan_period_plan_weekday') CREATE INDEX idx_recording_plan_period_plan_weekday ON gb_recording_plan_period(plan_id,weekday);
IF OBJECT_ID('gb_recording_plan_binding','U') IS NULL CREATE TABLE gb_recording_plan_binding (id BIGINT IDENTITY(1,1) PRIMARY KEY, plan_id BIGINT NOT NULL, channel_id BIGINT NOT NULL, owner_dept_id BIGINT NOT NULL, assigned_by BIGINT NOT NULL DEFAULT 0, assigned_at DATETIME2(3) NOT NULL, created_at DATETIME2(3) NOT NULL, updated_at DATETIME2(3) NOT NULL, CONSTRAINT uk_recording_plan_binding_channel UNIQUE(channel_id));
IF OBJECT_ID('gb_recording_plan_channel_state','U') IS NULL CREATE TABLE gb_recording_plan_channel_state (channel_id BIGINT PRIMARY KEY, plan_id BIGINT NULL, plan_version BIGINT NOT NULL DEFAULT 0, desired_state NVARCHAR(24) NOT NULL, actual_state NVARCHAR(32) NOT NULL, reason_code NVARCHAR(64) NOT NULL DEFAULT '', reason_message NVARCHAR(500) NOT NULL DEFAULT '', next_transition_at DATETIME2(3) NULL, next_retry_at DATETIME2(3) NULL, reconcile_at DATETIME2(3) NOT NULL, attempt_count INT NOT NULL DEFAULT 0, generation BIGINT NOT NULL DEFAULT 0, stream_id NVARCHAR(64) NOT NULL DEFAULT '', recording_session_id BIGINT NULL, node_id NVARCHAR(64) NOT NULL DEFAULT '', last_media_at DATETIME2(3) NULL, last_success_at DATETIME2(3) NULL, lease_owner NVARCHAR(128) NOT NULL DEFAULT '', lease_until DATETIME2(3) NULL, state_version BIGINT NOT NULL DEFAULT 0, created_at DATETIME2(3) NOT NULL, updated_at DATETIME2(3) NOT NULL);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name='idx_recording_plan_state_reconcile') CREATE INDEX idx_recording_plan_state_reconcile ON gb_recording_plan_channel_state(reconcile_at,channel_id);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name='idx_recording_plan_state_retry') CREATE INDEX idx_recording_plan_state_retry ON gb_recording_plan_channel_state(next_retry_at,channel_id);
IF OBJECT_ID('gb_recording_plan_execution','U') IS NULL CREATE TABLE gb_recording_plan_execution (id BIGINT IDENTITY(1,1) PRIMARY KEY, plan_id BIGINT NULL, channel_id BIGINT NOT NULL, device_id NVARCHAR(20) NOT NULL DEFAULT '', action NVARCHAR(32) NOT NULL, trigger_source NVARCHAR(32) NOT NULL, stage NVARCHAR(32) NOT NULL DEFAULT '', attempt INT NOT NULL DEFAULT 1, result NVARCHAR(24) NOT NULL, reason_code NVARCHAR(64) NOT NULL DEFAULT '', reason_message NVARCHAR(500) NOT NULL DEFAULT '', stream_id NVARCHAR(64) NOT NULL DEFAULT '', node_id NVARCHAR(64) NOT NULL DEFAULT '', recording_session_id BIGINT NULL, generation BIGINT NOT NULL DEFAULT 0, started_at DATETIME2(3) NOT NULL, ended_at DATETIME2(3) NULL, duration_ms BIGINT NOT NULL DEFAULT 0, created_at DATETIME2(3) NOT NULL);
IF OBJECT_ID('gb_recording_plan_gap','U') IS NULL CREATE TABLE gb_recording_plan_gap (id BIGINT IDENTITY(1,1) PRIMARY KEY, plan_id BIGINT NULL, channel_id BIGINT NOT NULL, started_at DATETIME2(3) NOT NULL, ended_at DATETIME2(3) NULL, duration_ms BIGINT NOT NULL DEFAULT 0, reason_code NVARCHAR(64) NOT NULL, reason_message NVARCHAR(500) NOT NULL DEFAULT '', recovered BIT NOT NULL DEFAULT 0, execution_id BIGINT NULL, created_at DATETIME2(3) NOT NULL, updated_at DATETIME2(3) NOT NULL);
